  advanceVok1,
  advanceVok2,
  advanceZef1,
  advanceZef2,
  advanceTal1,
  advanceOsk1,
  advanceOskFen,
  advanceFen1,
  advanceFen2,
};

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export const protocol: WorldProtocol = {
  reset: () => createInitialWorld(),

  applyOperation: (state, operationDisplayName) => {
    const operation = operations[operationDisplayName];
    if (typeof operation !== "function") {
      return {
        success: false,
        error: `Unknown operation: ${operationDisplayName}`,
      };
    }

    try {
      return { success: true, newState: operation(state) };
    } catch (error) {
      return { success: false, error: errorText(error) };
    }
  },

  getEntityState: (state, entityDisplayName) => {
    switch (entityDisplayName) {
      case "Vok":
        return state.vok;
      case "Zef":
        return state.zef;
      case "Tal":
        return state.tal;
      case "Osk":
        return state.osk;
      case "Fen":
        return state.fen;
      default:
        return "unknown";
    }
  },

  toAbstractSnapshot: (state) => ({
    Vok: state.vok,
    Zef: state.zef,
    Tal: state.tal,
    Osk: state.osk,
    Fen: state.fen,
  }),
};
